from sbxcpp.space import Space, Tilemap, BodyID, BodyFlags, set_tile_brick_height, get_tile_brick_height, TILE_BRICK_LAYERS, TILE_INDEX_BITS
from godot.classes import Array
from vmath import vec3, vec3i
import math

# set_tile_brick_height(0.5)

BASE_TILE = 1
WALL_TILE = 2
STAIR_W_TILE = 3
STAIR_N_TILE = 4

# What a click places, as the scene's toolbar numbers it.
PLACE_BRICK, PLACE_STAIR_W, PLACE_STAIR_N = 0, 1, 2

# A stair climbs in four steps toward the west or the north, away from the
# dimetric camera, so its steps face it. The steps are four boxes stacked bottom
# to top and the lowest fills the cell, which leaves the whole stair the aabb of
# a full brick. The rule tile never reshapes them: every key gets these boxes.
STAIR_STEPS = 4

# Rises about 1.2 under the playground's gravity, enough to get on top of a wall
# or out of a hole, both one brick high.
JUMP_SPEED = 5.0

# A body at rest sinks into its floor by up to the engine's linear slop, so the
# plane under the hero's feet is looked up with a little room to spare.
REST_SLOP = 0.05

# A few mobs to try BodyFlags.SOFT on. They walk straight at the hero, with no
# path finding, and like the hero they take stairs on their own. While the
# playground is soft, the hero and the mobs carry the flag: they walk into each
# other and are pushed apart, as in Minecraft, the hero as much as any mob.
# Without it they are as solid to each other as walls, and a ring of mobs holds
# the hero where it stands.
MOB_COUNT = 6
MOB_SPEED = 2.0
MOB_EXTENT = vec3(0.3, 0.45, 0.3)
# a mob this close to the hero stops walking, so it does not shake on the spot
MOB_ARRIVE = 0.05

# The 3 bit rule tile of spelltide-sbx docs/html/wall-rule-tile-16.html.
# get_tile_body() in Space.cpp turns every brick, on all four layers, by its key
# W * 1 + N * 2 + NW * 4, read from the bricks west (-X), north (-Z) and
# north-west of it on its own layer, and each key of a tile owns its own body. A
# brick always fills the +X+Z corner of its cell, the one nearest the dimetric
# camera, and reaches into the cell's west or north half only toward a neighbor
# there. The diagonal tells the two ways of having both apart: with it the whole
# cell, without it the L that leaves the north-west quarter open.
GROUND_LAYERS = 2
PILLAR, WALL_SW, WALL_SE, WALL_L, FULL = 0, 1, 2, 3, 4
RULE_TILE_NAMES = ('PILLAR', 'WALL_SW', 'WALL_SE', 'WALL_L', 'FULL')
# the parts (x0, z0, x1, z1) of its cell each variant fills; the L is the only
# one that takes two of them, which is why a brick body may be a compound
RULE_TILE_PARTS = (
    ((0.5, 0.5, 1.0, 1.0),),                        # PILLAR: the corner alone
    ((0.0, 0.5, 1.0, 1.0),),                        # WALL_SW: along the +Z edge
    ((0.5, 0.0, 1.0, 1.0),),                        # WALL_SE: along the +X edge
    ((0.0, 0.5, 1.0, 1.0), (0.5, 0.0, 1.0, 0.5)),   # WALL_L: both, cut apart along +Z
    ((0.0, 0.0, 1.0, 1.0),),                        # FULL: the whole cell
)
# the variant each key uses; the diagonal only tells key 3, the L, from key 7,
# so keys 0-2 come back unchanged at 4-6
RULE_TILE_KEYS = (PILLAR, WALL_SW, WALL_SE, WALL_L, PILLAR, WALL_SW, WALL_SE, FULL)
KEY_NAMES = ('-', 'W', 'N', 'W+N', 'NW', 'W+NW', 'N+NW', 'W+N+NW')

# The page's map of all 16 masks (全部 16 种 mask), the playground's walls at the
# start: rows run north to south (-Z to +Z), columns west to east (-X to +X),
# and '#' is a wall.
ALL16 = (
    '................',
    '.#####.....#....',
    '.#...#.....#....',
    '.#.......#####..',
    '.#...#.....#....',
    '.#####.....#....',
    '......###.......',
    '.#....###.....#.',
    '......###.......',
    '.#####...#...#..',
    '...#.....#...#..',
    '...#.....#####..',
    '...#.....#...#..',
    '.#####...#...#..',
    '................',
    '................',
)

def pretty_vec3(v: vec3) -> str:
    return f"({v.x:8.4f}, {v.y:8.4f}, {v.z:8.4f})"

def cell_box(x0: float, z0: float, x1: float, z1: float, y0: float, y1: float, h: float):
    # one box of a tile body as an (offset, extent) pair: the part
    # (x0, z0, x1, z1) of the cell between the heights y0 and y1, given around
    # the middle of the cell at half the brick's height
    offset = vec3(x0 + x1 - 1, y0 + y1 - h, z0 + z1 - 1) * 0.5
    extent = vec3(x1 - x0, y1 - y0, z1 - z0) * 0.5
    return (offset, extent)

def stair_boxes(h: float, north: bool):
    # The steps of a stair, the lowest one filling the cell and each one above
    # it a quarter shorter, so the stair climbs toward the north or the west.
    boxes = []
    for i in range(STAIR_STEPS):
        reach = 1.0 - i / STAIR_STEPS
        y0 = i / STAIR_STEPS * h
        y1 = (i + 1) / STAIR_STEPS * h
        if north:
            boxes.append(cell_box(0.0, 0.0, 1.0, reach, y0, y1, h))
        else:
            boxes.append(cell_box(0.0, 0.0, reach, 1.0, y0, y1, h))
    return boxes

class Playground:
    def on_pair_add(self, a: BodyID, b: BodyID, xzl: vec3i, normal: vec3, max_sep: float):
        print(f"on_pair_add: a={a}, b={b}, xzl={xzl}, normal={normal}, max_sep={max_sep}")
    def on_pair_remove(self, a: BodyID, b: BodyID, xzl: vec3i):
        print(f"on_pair_remove: a={a}, b={b}, xzl={xzl}")

    def __init__(self):
        tilemap = Tilemap(30, 30)
        self.space = Space(tilemap, 10, self)

        # generate: two full floor layers, and ALL16 as walls on layer 2 in the
        # middle of the map
        for x in range(tilemap.width):
            for y in range(tilemap.height):
                tilemap.set(x, y, 0, BASE_TILE)
                tilemap.set(x, y, 1, BASE_TILE)
        x0 = (tilemap.width - len(ALL16[0])) // 2
        y0 = (tilemap.height - len(ALL16)) // 2
        for r in range(len(ALL16)):
            for c in range(len(ALL16[r])):
                if ALL16[r][c] == '#':
                    tilemap.set(x0 + c, y0 + r, 2, WALL_TILE)

        # A body is told its flags once, as it is created. CAN_STEP: the hero takes
        # the stairs on its own, a quarter of a brick at a time. Adding
        # BodyFlags.MONITORING would have it report every tile and body it touches
        # through on_pair_add() and on_pair_remove() above.
        self.soft = True # whether the hero and the mobs carry BodyFlags.SOFT
        self.chasing = True # whether the mobs walk at the hero or stand still
        self.hero = self.create_actor(vec3(0.24, 0.75, 0.24), vec3(19.44, 2.5, 14.36))
        self.mobs = []
        for x, z in self.free_cells_near(19, 14, MOB_COUNT):
            self.mobs.append(self.create_actor(MOB_EXTENT, vec3(x + 0.5, 1.0, z + 0.5)))
        self.space.gravity = vec3(0, -9.81, 0)
        self.on_floor = False

        # Ground and walls alike take the rule tile, so each of them owns one
        # body per key. A body is authored with its bottom at the slot's height,
        # its parts offset around the center of the cell.
        h = get_tile_brick_height()
        for tile in (BASE_TILE, WALL_TILE):
            for key in range(len(RULE_TILE_KEYS)):
                boxes = []
                for x0, z0, x1, z1 in RULE_TILE_PARTS[RULE_TILE_KEYS[key]]:
                    boxes.append(cell_box(x0, z0, x1, z1, 0.0, h, h))
                self.space.create_tile_body(tile | key << TILE_INDEX_BITS, boxes, vec3(0, h * 0.5, 0), 0)
        for tile, north in ((STAIR_W_TILE, False), (STAIR_N_TILE, True)):
            steps = stair_boxes(h, north)
            for key in range(len(RULE_TILE_KEYS)):
                self.space.create_tile_body(tile | key << TILE_INDEX_BITS, steps, vec3(0, h * 0.5, 0), 0)

        # the topmost brick of the aimed column and the slot on top of it, as
        # vec3i(x, z, layer), or None
        self.aim_brick = None
        self.aim_slot = None

    def create_actor(self, extent: vec3, position: vec3) -> BodyID:
        # The hero or a mob: a kinematic body that falls and takes stairs. A body
        # keeps the flags it is created with, so whether it is soft is decided here.
        flags = BodyFlags.CAN_STEP
        if self.soft:
            flags |= BodyFlags.SOFT
        body = self.space.create_body(2, extent, flags)
        self.space.body_set_gravity_scale(body, 1.0)
        self.space.teleport_body(body, position)
        return body

    def free_cells_near(self, x: int, z: int, count: int) -> list:
        # `count` cells a mob can stand in, spreading out from (x, z) over the
        # cells that have a floor and no wall, a breadth-first walk that skips
        # the first few so that nobody starts on top of the hero
        tilemap = self.space.tilemap
        seen = {(x, z)}
        queue = [(x, z)]
        found = []
        skipped = 0
        while len(queue) > 0 and len(found) < count:
            cx, cz = queue.pop(0)
            skipped += 1
            if skipped > 4 and skipped % 3 == 0:
                found.append((cx, cz))
            for dx, dz in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx = (cx + dx) % tilemap.width
                nz = (cz + dz) % tilemap.height
                if (nx, nz) in seen:
                    continue
                seen.add((nx, nz))
                if tilemap.get(nx, nz, 1) != 0 and tilemap.get(nx, nz, 2) == 0:
                    queue.append((nx, nz))
        return found

    def drive_mobs(self):
        # each mob heads for the hero along the shortest way around the torus
        hero = self.space.body_get_position(self.hero)
        for mob in self.mobs:
            to = self.space.diff_point(hero, self.space.body_get_position(mob))
            distance = math.sqrt(to.x * to.x + to.z * to.z)
            vel_y = self.space.body_get_velocity(mob).y
            if self.chasing and distance > MOB_ARRIVE:
                scale = MOB_SPEED / distance
                self.space.body_set_velocity(mob, vec3(to.x * scale, vel_y, to.z * scale))
            else:
                self.space.body_set_velocity(mob, vec3(0, vel_y, 0))

    def mob_positions(self) -> Array:
        # where the last step left the mobs, in a Godot container for the scene
        places = Array()
        for mob in self.mobs:
            places.append(self.space.body_get_position(mob))
        return places

    def mob_info(self) -> str:
        # what the mobs are and do, and the keys that change it, for the scene's top row
        kind = 'soft' if self.soft else 'solid'
        doing = 'chase' if self.chasing else 'stand'
        return f"{len(self.mobs)} mobs: {kind}, {doing}   [F] soft / solid   [G] chase / stand"

    def toggle_chase(self) -> bool:
        self.chasing = not self.chasing
        return self.chasing

    def toggle_soft(self) -> bool:
        # A body's flags never change, so the hero and the mobs are created anew:
        # the hero where it stands and as fast as it moves, the mobs on free
        # cells around it, clear of each other. Solid bodies that started out
        # inside one another would not hold each other, which is how the space
        # lets a body out of whatever it is stuck in.
        self.soft = not self.soft
        position = self.space.body_get_position(self.hero)
        velocity = self.space.body_get_velocity(self.hero)
        for body in [self.hero] + self.mobs:
            self.space.destroy_body(body)
        self.hero = self.create_actor(vec3(0.24, 0.75, 0.24), position)
        self.space.body_set_velocity(self.hero, velocity)
        feet = position.y - 0.75
        self.mobs = []
        for x, z in self.free_cells_near(math.floor(position.x), math.floor(position.z), MOB_COUNT):
            self.mobs.append(self.create_actor(MOB_EXTENT, vec3(x + 0.5, max(feet, 0.0) + 1.0, z + 0.5)))
        return self.soft

    def move_hero_and_step(self, vel_x: float, vel_z: float, delta: float, jump: bool = False):
        # With its gravity scale, the hero gains each step's gravity right before
        # its sweep, which slides it across tile seams without catching on them
        # and zeroes vel_y whenever the floor stops its fall.
        if jump and self.on_floor:
            vel_y = JUMP_SPEED
        else:
            vel_y = self.space.body_get_velocity(self.hero).y
        self.space.body_set_velocity(self.hero, vec3(vel_x, vel_y, vel_z))
        self.drive_mobs()
        self.space.step(delta)
        # Standing or falling, a step that ends with vel_y zeroed was stopped by a
        # floor. A ceiling zeroes a rise instead, so it never allows a jump.
        self.on_floor = vel_y <= 0 and self.space.body_get_velocity(self.hero).y == 0
        return self.space.body_get_position(self.hero)

    def map_info(self) -> Array:
        # [width, height, chunk size, brick height, hero extent, mob extent, mob
        # count] for the scene's scripts, in a Godot container, because a Python
        # list has no Variant counterpart to cross PythonScript.eval() with
        info = Array()
        info.append(self.space.tilemap.width)
        info.append(self.space.tilemap.height)
        info.append(self.space.chunk_size)
        info.append(get_tile_brick_height())
        info.append(self.space.body_get_aabb_extent(self.hero))
        info.append(MOB_EXTENT)
        info.append(len(self.mobs))
        return info

    def brick_key(self, x: int, z: int, layer: int) -> int:
        # the key get_tile_body() picks the body of the brick at (x, z) by
        tilemap = self.space.tilemap
        key = 0
        if tilemap.get(x - 1, z, layer) != 0:
            key |= 1
        if tilemap.get(x, z - 1, layer) != 0:
            key |= 2
        if tilemap.get(x - 1, z - 1, layer) != 0:
            key |= 4
        return key

    def aim_ray(self, ox: float, oy: float, oz: float, dx: float, dy: float, dz: float):
        # Aims along the ray from (ox, oy, oz) toward (dx, dy, dz), the one through
        # the cursor, at the cell where it crosses the hero's own plane, the one
        # its clicks reach, whatever bricks stand in the way, so adding or
        # removing one never moves the aim. Only the map as the scene draws it,
        # [0, width) x [0, height), can be aimed at, because the tiles repeating
        # around it across the torus seam are not drawn. Returns the cell and that
        # plane's layer, as aim_cell() does, or None.
        if dy >= 0:
            return self.aim_clear()
        plane_y = (self.plane_layer() - GROUND_LAYERS) * get_tile_brick_height()
        t = (plane_y - oy) / dy
        x = math.floor(ox + dx * t)
        z = math.floor(oz + dz * t)
        tilemap = self.space.tilemap
        if x < 0 or z < 0 or x >= tilemap.width or z >= tilemap.height:
            return self.aim_clear()
        return self.aim_cell(x, z)

    def plane_layer(self) -> int:
        # The layer standing on the plane under the hero's feet. Brick layer l
        # stands at (l - GROUND_LAYERS) * brick height, so this is the slot the
        # hero's own feet rest on top of.
        feet = self.space.body_get_position(self.hero).y - self.space.body_get_aabb_extent(self.hero).y
        return math.floor((feet + REST_SLOP) / get_tile_brick_height()) + GROUND_LAYERS

    def has_brick(self, x: int, z: int, layer: int) -> bool:
        return 0 <= layer < TILE_BRICK_LAYERS and self.space.tilemap.get(x, z, layer) != 0

    def aim_cell(self, x: int, z: int) -> vec3i:
        # Aims at the cell (x, z) around the hero's own plane, which a click
        # reaches one layer to either side of: the slot standing on the plane and
        # the one right under it, no further. Each of the two holds one brick, so
        # digging deeper or stacking higher means standing there first. Bricks
        # never hang in the air: one goes on top of another, and only the topmost
        # of the two comes out. Returns the cell and the plane's layer, for the
        # scene to lay its marker on.
        layer = self.plane_layer()
        self.aim_slot = None
        for l in (layer - 1, layer):
            if 0 <= l < TILE_BRICK_LAYERS and not self.has_brick(x, z, l) and (l == 0 or self.has_brick(x, z, l - 1)):
                self.aim_slot = vec3i(x, z, l)
                break
        self.aim_brick = None
        for l in (layer, layer - 1):
            if self.has_brick(x, z, l) and not self.has_brick(x, z, l + 1):
                self.aim_brick = vec3i(x, z, l)
                break
        return vec3i(x, z, layer)

    def aim_clear(self):
        self.aim_brick = None
        self.aim_slot = None

    def place(self, kind: int = 0) -> bool: # 0 is PLACE_BRICK; pocketpy wants a literal here
        # a brick is BASE on the ground and WALL above it; a stair is its own
        # tile and keeps its shape on every layer
        slot = self.aim_slot
        if slot is None:
            return False
        if kind == PLACE_STAIR_W:
            tile = STAIR_W_TILE
        elif kind == PLACE_STAIR_N:
            tile = STAIR_N_TILE
        else:
            tile = BASE_TILE if slot.z < GROUND_LAYERS else WALL_TILE
        return self.space.create_tile(slot.x, slot.y, slot.z, tile)

    def remove(self) -> bool:
        brick = self.aim_brick
        if brick is None:
            return False
        return self.space.destroy_tile(brick.x, brick.y, brick.z)

    def aim_text(self) -> str:
        slot = self.aim_slot
        brick = self.aim_brick
        cell = slot if slot is not None else brick
        if cell is None:
            return f"- , plane {self.plane_layer()}"
        text = f"({cell.x}, {cell.y}) plane {self.plane_layer()}"
        if slot is not None:
            text += f", place layer {slot.z}"
        if brick is not None:
            tile = self.space.tilemap.get(brick.x, brick.y, brick.z)
            if tile == STAIR_W_TILE or tile == STAIR_N_TILE:
                stair = 'stair N' if tile == STAIR_N_TILE else 'stair W'
                text += f", remove layer {brick.z} {stair}"
            else:
                key = self.brick_key(brick.x, brick.y, brick.z)
                name = RULE_TILE_NAMES[RULE_TILE_KEYS[key]]
                text += f", remove layer {brick.z} key {key} ({KEY_NAMES[key]}) -> {name}"
        return text

    def debug_info(self) -> str:
        lines = []
        position = self.space.body_get_position(self.hero)
        chunk_index = self.space.body_get_chunk_index(self.hero)
        velocity = self.space.body_get_velocity(self.hero)
        lines.append(f"position: {pretty_vec3(position)}")
        lines.append(f"chunk index: {chunk_index}")
        lines.append(f"velocity: {pretty_vec3(velocity)}")
        lines.append(f"on floor: {self.on_floor}")
        lines.append(f"aim: {self.aim_text()}")
        lines.append("arrows or WASD: move, space: jump")
        lines.append("LMB: place, RMB: remove, one layer either side of your plane")
        return "\n".join(lines)


instance = Playground()
